using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
namespace OpenAntiLag {
 public sealed class GameSessionMarker {public string GameId,Executable,OwnedPlan;public bool Applying,SeenGameRunning;public DateTime StartedUtc;}
 public interface IGameSessionStore {GameSessionMarker Load();void Save(GameSessionMarker value);void Clear();}
 public sealed class GameSessionStore:IGameSessionStore {
  readonly string path;public GameSessionStore(string path=null){this.path=path??Path.Combine(Program.DataDirectory,"game-session.json");}
  public GameSessionMarker Load(){if(!File.Exists(path))return null;if(new FileInfo(path).Length>16384)throw new InvalidDataException("Повреждён журнал игровой сессии");var value=new JavaScriptSerializer().Deserialize<GameSessionMarker>(File.ReadAllText(path));Guid id;if(value==null||String.IsNullOrEmpty(value.GameId)||String.IsNullOrEmpty(value.Executable)||!Path.IsPathRooted(value.Executable)||(!value.Applying&&!Guid.TryParse(value.OwnedPlan,out id)))throw new InvalidDataException("Не удалось подтвердить владельца автоматического профиля");return value;}
  public void Save(GameSessionMarker value){AtomicLocalFile.Write(path,System.Text.Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(value)));}public void Clear(){if(File.Exists(path))File.Delete(path);if(File.Exists(path+".bak"))File.Delete(path+".bak");}
 }
 public sealed class GameSessionController {
  readonly OptimizationOrchestrator optimizer;readonly IGameSessionStore store;public bool Faceit {get;private set;}public bool Running {get;private set;}public string Message {get;private set;}public DateTime? LastStartUtc {get;private set;}public DateTime? LastEndUtc {get;private set;}bool ticking;string lastAttempt,suppressedId,suppressedExecutable;
  public GameSessionController(OptimizationOrchestrator optimizer,IGameSessionStore store){this.optimizer=optimizer;this.store=store;}
  public static bool Matches(InstalledGame game,GameProcess process){return game!=null&&game.CanWatch&&process!=null&&!String.IsNullOrEmpty(process.Path)&&String.Equals(Path.GetFullPath(game.Executable),Path.GetFullPath(process.Path),StringComparison.OrdinalIgnoreCase);}
  static bool SameExecutable(string executable,GameProcess p){return !String.IsNullOrEmpty(p.Path)&&String.Equals(executable,p.Path,StringComparison.OrdinalIgnoreCase);}
  public async Task Tick(InstalledGame selected,GameProcess[] processes){if(ticking||optimizer.Status.Busy)return;ticking=true;try{Faceit=processes.Any(p=>p.Name.IndexOf("faceit",StringComparison.OrdinalIgnoreCase)>=0);optimizer.Status.Faceit=Faceit;bool was=Running;Running=processes.Any(p=>Matches(selected,p));if(!Running)lastAttempt=null;if(suppressedExecutable!=null&&!processes.Any(p=>SameExecutable(suppressedExecutable,p))){suppressedId=null;suppressedExecutable=null;}if(Running&&!was)LastStartUtc=DateTime.UtcNow;if(!Running&&was)LastEndUtc=DateTime.UtcNow;var marker=store.Load();
   if(marker!=null){var state=await Task.Run(()=>optimizer.Read());if(state.UserPhase=="Disabled"){store.Clear();return;}if(marker.Applying||String.IsNullOrEmpty(marker.OwnedPlan)||marker.OwnedPlan!=state.OwnedPlan){Message="После сбоя нужно проверить восстановление профиля. Автоматический откат не подтверждён.";return;}bool ownedRunning=processes.Any(p=>SameExecutable(marker.Executable,p));if(ownedRunning&&!marker.SeenGameRunning){marker.SeenGameRunning=true;store.Save(marker);}if(!ownedRunning&&!marker.SeenGameRunning){Message="Профиль включён. Ожидаем запуск выбранной игры для автоматического восстановления после неё.";return;}if(!ownedRunning){Message="Игра завершена. Восстанавливаем её автоматический профиль…";await optimizer.Restore(true);var after=await Task.Run(()=>optimizer.Read());if(after.UserPhase=="Disabled"){store.Clear();Message="Автоматический профиль игры восстановлен.";}else Message="Восстановление не завершено. Откройте экран восстановления.";}return;}
   if(selected==null||!selected.Automatic)return;if(suppressedId==selected.Id){Message="Автоматическое применение выключено для текущего запуска игры. Следующая попытка — после её перезапуска.";return;}if(!Running){Message=selected.CanWatch?"Автоматический профиль: ожидание запуска игры.":"Для автоматического профиля нужно указать EXE игры.";return;}if(selected.Profile==PlayerProfile.Custom){Message="Пользовательский профиль применяется вручную после просмотра изменений.";return;}var baseline=await Task.Run(()=>optimizer.Read());if(baseline.UserPhase!="Disabled"||baseline.MachinePhase!="Disabled"||baseline.Reboot){Message="Автоматическое применение отложено: сначала восстановите существующий профиль или перезагрузите Windows.";return;}
   var process=processes.First(p=>Matches(selected,p));string runKey=selected.Id+":"+process.Id;if(lastAttempt==runKey){Message="Автоматическая попытка в этом запуске игры уже выполнена. Повторите действие вручную или перезапустите игру.";return;}lastAttempt=runKey;var beforeOperation=optimizer.Operations().LastOrDefault();
   var pending=new GameSessionMarker {GameId=selected.Id,Executable=selected.Executable,StartedUtc=DateTime.UtcNow,Applying=true,SeenGameRunning=true};store.Save(pending);bool enabled=await optimizer.Enable(selected.Profile,OptimizationOrchestrator.Options(selected.Profile),new string[0],selected.Id);var applied=await Task.Run(()=>optimizer.Read());if(enabled&&applied.UserPhase=="Enabled"&&applied.Active&&optimizer.Status.Stage==OptimizationStage.Enabled){pending.OwnedPlan=applied.OwnedPlan;pending.Applying=false;store.Save(pending);Message="Автоматический профиль применён. Он восстановится после завершения игры.";}else{if(applied.UserPhase=="Disabled")store.Clear();if(Object.ReferenceEquals(beforeOperation,optimizer.Operations().LastOrDefault()))lastAttempt=null;Message=optimizer.Status.Message;}
  }catch(Exception error){Message="Автоматическое применение остановлено: "+error.Message;}finally{ticking=false;}}
  public void SuppressCurrentRun(InstalledGame selected,GameProcess[] processes){GameSessionMarker marker=null;try{marker=store.Load();}catch(Exception error){Message="Журнал игровой сессии недоступен: "+error.Message;}string executable=marker==null?(selected==null?null:selected.Executable):marker.Executable;string id=marker==null?(selected==null?null:selected.Id):marker.GameId;if(executable!=null&&processes.Any(p=>SameExecutable(executable,p))){suppressedId=id;suppressedExecutable=executable;}}
  public async Task ApplyManual(InstalledGame game,GameProcess[] processes){if(game==null||!game.CanWatch||game.Profile==PlayerProfile.Custom)throw new InvalidOperationException("Для привязанного профиля нужна игра с EXE и стандартный либо соревновательный профиль");var baseline=await Task.Run(()=>optimizer.Read());if(baseline.UserPhase!="Disabled"||baseline.MachinePhase!="Disabled"||baseline.Reboot)throw new InvalidOperationException("Сначала восстановите существующий профиль");var marker=new GameSessionMarker {GameId=game.Id,Executable=game.Executable,Applying=true,StartedUtc=DateTime.UtcNow,SeenGameRunning=processes.Any(p=>Matches(game,p))};store.Save(marker);bool success=await optimizer.Enable(game.Profile,OptimizationOrchestrator.Options(game.Profile),new string[0],game.Id);var state=await Task.Run(()=>optimizer.Read());if(success){marker.OwnedPlan=state.OwnedPlan;marker.Applying=false;store.Save(marker);}else if(state.UserPhase=="Disabled")store.Clear();}
  public async Task RestoreOwned(){var marker=store.Load();if(marker==null)return;var state=await Task.Run(()=>optimizer.Read());if(state.UserPhase=="Disabled"){store.Clear();return;}if(marker.Applying||marker.OwnedPlan!=state.OwnedPlan)throw new InvalidOperationException("Нельзя автоматически восстановить профиль с неподтверждённым владельцем");await optimizer.Restore(true);if((await Task.Run(()=>optimizer.Read())).UserPhase!="Disabled")throw new IOException("Автоматический профиль не восстановлен");store.Clear();}
 }
 public sealed class SessionMeasurements:IDisposable {
  readonly PerformanceMonitor monitor=new PerformanceMonitor();readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);CancellationTokenSource cancel;Task running;int trackedPid;bool disposed;
  public bool Enabled {get;private set;}public PerformanceSample Last {get;private set;}public string Message="Измерение не запущено";public event Action Changed;
  public SessionMeasurements(){monitor.Sample+=s=>{Last=s;var h=Changed;if(h!=null)h();};}
  public async Task Configure(bool value,int processId){await gate.WaitAsync();try{if(disposed)return;Enabled=value;if(value&&processId>0&&processId==trackedPid&&running!=null&&!running.IsCompleted)return;if(cancel!=null){cancel.Cancel();if(running!=null)await running;cancel.Dispose();cancel=null;}trackedPid=processId;if(!value||processId<=0){Message=value?"Измерение включится после запуска выбранной игры":"Измерение выключено";return;}cancel=new CancellationTokenSource();var token=cancel.Token;running=Task.Run(async delegate{try{Message="Измеряются CPU и RAM";await monitor.Run(processId,3600,2000,token);Message="Измерение завершено";}catch(OperationCanceledException){Message="Измерение остановлено";}catch(Exception error){Message=error.Message;}finally{var h=Changed;if(h!=null)h();}});}finally{gate.Release();}}
  public PerformanceSample[] Samples(){return monitor.Snapshot();}public void Dispose(){disposed=true;if(cancel!=null)cancel.Cancel();}
 }
}
